from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, write_time]
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # check if key exists but expired
            if key in cache:
                _, wt = cache[key]
                if t - wt >= ttl:
                    del cache[key]
            if key in cache:
                cache[key] = [value, t]
                cache.move_to_end(key)
            else:
                # need to possibly evict, but first remove expired entries counted as absent
                if len(cache) >= capacity:
                    # evict least recently used (first item), but first check if any expired to just remove them doesn't matter since eviction is about count
                    # evict LRU
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)
        else:
            _, t, key = op
            if key in cache:
                value, wt = cache[key]
                if t - wt >= ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    results.append(value)
                    cache.move_to_end(key)
            else:
                results.append(-1)
    return results

